"""GD11 head-refinement D (protects B, C, D, E and F) checkpoint / verify (run from the project root, any Python 3). Hashes every protected Content group (*.u*), the GD15 candidate,
all earlier character source folders under SourceAssets/Characters and the reference images, before the GD16 work.
usage: python gd16_checkpoint.py [--verify]   -> writes data/checkpoint_hashes.json or data/preservation_check.json"""
import hashlib, pathlib, json, datetime, sys
G = pathlib.Path('Saved/Codex/GD11_HeadRefinementL_20261005')
GROUPS = {'GD11 HeadRefinement R3/h32 (b44c08a)': 'Sphirus/CharacterLab/GD11_HeadRefinement_20261003', 'GD11 HeadRefinement B D85/h34 (a183736)': 'Sphirus/CharacterLab/GD11_HeadRefinementB_20261004', 'GD11 HeadRefinement C F3/h37/k10': 'Sphirus/CharacterLab/GD11_HeadRefinementC_20261004', 'GD11 HeadRefinement D F4ab/h38d (face of F)': 'Sphirus/CharacterLab/GD11_HeadRefinementD_20261004', 'GD11 HeadRefinement E h39i': 'Sphirus/CharacterLab/GD11_HeadRefinementE_20261004', 'GD11 HeadRefinement F h40d': 'Sphirus/CharacterLab/GD11_HeadRefinementF_20261004', 'GD11 HeadRefinement G h41f': 'Sphirus/CharacterLab/GD11_HeadRefinementG_20261004', 'GD11 HeadRefinement H h42d': 'Sphirus/CharacterLab/GD11_HeadRefinementH_20261004', 'GD11 HeadRefinement I h43i': 'Sphirus/CharacterLab/GD11_HeadRefinementI_20261004', 'GD11 HeadRefinement J h45b (active start)': 'Sphirus/CharacterLab/GD11_HeadRefinementJ_20261005', 'GD11 HeadRefinement K K5/h46a (rejected record)': 'Sphirus/CharacterLab/GD11_HeadRefinementK_20261005', 'production MH_MainCharacter': 'MetaHumans/MH_MainCharacter', 'accepted B2': 'Sphirus/CharacterLab/NativeBody_20260928', 'accepted SHCB HelperFix': 'Sphirus/CharacterLab/ShoulderFix_20260928/HighElevCorrective/HelperFix', 'BR v5 candidate': 'Sphirus/CharacterLab/BodyRealism_20260929', 'Outfit V1 candidate': 'Sphirus/CharacterLab/Outfit_Home_20260929', 'ShoulderFix skeleton copies': 'Sphirus/CharacterLab/ShoulderFix_20260928/Common', 'CharacterFinal candidate': 'Sphirus/CharacterLab/CharacterFinal_20260929', 'CharacterRevision candidate': 'Sphirus/CharacterLab/CharacterRevision_20260930', 'Lookdev candidate 889b1d9': 'Sphirus/CharacterLab/CharacterLookdev_20260930', 'Identity candidate 6255d92': 'Sphirus/CharacterLab/CharacterIdentity_20260930', 'Corrective candidate 2e60b34': 'Sphirus/CharacterLab/CharacterCorrective_20261001', 'Guardian candidate dcb061c': 'Sphirus/CharacterLab/CharacterGuardian_20261001', 'Guardian2 candidate e9f3149 (P baseline)': 'Sphirus/CharacterLab/CharacterGuardian2_20261001', 'Guardian3 candidate e89a554 (N7 baseline)': 'Sphirus/CharacterLab/CharacterGuardian3_20261001', 'Guardian4 candidate 8914968 (E1 baseline)': 'Sphirus/CharacterLab/CharacterGuardian4_20261002', 'Guardian5 candidate 545d03d (F5 baseline)': 'Sphirus/CharacterLab/CharacterGuardian5_20261002', 'Guardian6 candidate 2c5f436 (S4)': 'Sphirus/CharacterLab/CharacterGuardian6_20261002', 'Guardian7 candidate fab11ef (C8 / h17)': 'Sphirus/CharacterLab/CharacterGuardian7_20261002', 'Guardian8 candidate 3b9cf73 (h23)': 'Sphirus/CharacterLab/CharacterGuardian8_20261002', 'Guardian9 candidate 4adbdbd (G)': 'Sphirus/CharacterLab/CharacterGuardian9_20261002', 'Guardian10 candidate 2881d1c (S5)': 'Sphirus/CharacterLab/CharacterGuardian10_20261002', 'Guardian11 candidate 58336a2 (E)': 'Sphirus/CharacterLab/CharacterGuardian11_20261002', 'Guardian12 candidate 0fc6130 (F)': 'Sphirus/CharacterLab/CharacterGuardian12_20261003', 'Guardian12C candidate d4f8c84 (G)': 'Sphirus/CharacterLab/CharacterGuardian12C_20261003', 'Guardian13 candidate (clay only)': 'Sphirus/CharacterLab/CharacterGuardian13_20261003', 'Guardian14 candidate 1d08ae6 (K2)': 'Sphirus/CharacterLab/CharacterGuardian14_20261003', 'MetaHumans Common (shared)': 'MetaHumans/Common', 'Guardian15 candidate 01d204e/79f4465 (N1/N2)': 'Sphirus/CharacterLab/CharacterGuardian15_20261003'}
SRC = sorted(p.name for p in pathlib.Path('SourceAssets/Characters').iterdir() if p.is_dir())
EXTRA = {'GD11 HeadRefinement source data': 'Saved/Codex/GD11_HeadRefinement_20261003', 'GD11 HeadRefinement B source data': 'Saved/Codex/GD11_HeadRefinementB_20261004', 'GD11 HeadRefinement C source data': 'Saved/Codex/GD11_HeadRefinementC_20261004', 'GD11 HeadRefinement D source data': 'Saved/Codex/GD11_HeadRefinementD_20261004', 'GD11 HeadRefinement E source data': 'Saved/Codex/GD11_HeadRefinementE_20261004', 'GD11 HeadRefinement F source data': 'Saved/Codex/GD11_HeadRefinementF_20261004', 'GD11 HeadRefinement G source data': 'Saved/Codex/GD11_HeadRefinementG_20261004', 'GD11 HeadRefinement H source data': 'Saved/Codex/GD11_HeadRefinementH_20261004', 'GD11 HeadRefinement I source data': 'Saved/Codex/GD11_HeadRefinementI_20261004', 'GD11 HeadRefinement J source data': 'Saved/Codex/GD11_HeadRefinementJ_20261005', 'GD11 HairJ SourceAssets': 'SourceAssets/Characters/GD11_HairJ_20261005', 'GD11 HeadRefinement K source data': 'Saved/Codex/GD11_HeadRefinementK_20261005', 'GD11 HeadK SourceAssets': 'SourceAssets/Characters/GD11_HeadK_20261005', 'GD11 FaceRevertStatus report data': 'Saved/Codex/GD11_FaceRevertStatus_20261005', 'Guardian11 source data': 'Saved/Codex/CharacterGuardian11_20261002', 'Guardian8 h23 hair source': 'Saved/Codex/CharacterGuardian8_20261002', 'reference concept_guardian_approved': 'Saved/Codex/CharacterRevision_20260930/reference', 'reference refB aids': 'Saved/Codex/CharacterGuardian2_20261001/refB',
         'reference track crops': 'Saved/Codex/CharacterIdentity_20260930/track', 'Guardian15 source data': 'Saved/Codex/CharacterGuardian15_20261003'}
def scan(root, pat):
    files = {}; h = hashlib.sha1()
    for f in sorted(pathlib.Path(root).rglob(pat)):
        if f.is_file():
            b = f.read_bytes(); files[f.relative_to(root).as_posix()] = hashlib.sha1(b).hexdigest()[:16]; h.update(f.name.encode()); h.update(b)
    return {'path': str(root), 'files': len(files), 'sha1_12': h.hexdigest()[:12], 'per_file': files}
def take():
    out = {}
    for k, d in GROUPS.items(): out[k] = scan(pathlib.Path('Content')/d, '*.u*')
    for s in SRC: out['source '+s] = scan(pathlib.Path('SourceAssets/Characters')/s, '*')
    for k, d in EXTRA.items(): out[k] = scan(pathlib.Path(d), '*')
    return out
if '--verify' in sys.argv:
    ck = json.load(open(G/'data/checkpoint_hashes.json')); now = take(); res = {}
    for k, v in ck['groups'].items():
        n = now.get(k, {'per_file': {}}); a, b = v['per_file'], n['per_file']
        res[k] = {'files': len(a), 'identical': a == b, 'changed': [f for f in a if f in b and a[f] != b[f]][:20], 'added': [f for f in b if f not in a][:20], 'removed': [f for f in a if f not in b][:20]}
    (G/'data/preservation_check.json').write_text(json.dumps({'checked': datetime.datetime.now().isoformat(timespec='seconds'), 'checkpoint_taken': ck['taken'], 'groups': res}, indent=1))
    print('VERIFY', sum(r['identical'] for r in res.values()), '/', len(res), [k for k, r in res.items() if not r['identical']])
else:
    out = {'taken': datetime.datetime.now().isoformat(timespec='seconds'), 'groups': take()}
    (G/'data/checkpoint_hashes.json').write_text(json.dumps(out, indent=1)); print('CHECKPOINT', len(out['groups']), {k: v['files'] for k, v in out['groups'].items()})
